<script type="application/ld+json" dangerouslySetInnerHTML={{__html:"\r\n{\n    \"@context\": \"https://schema.org\",\n    \"@type\": \"FAQPage\",\n    \"@id\": \"https://dizitaladda.com/courses/graphic-design-and-motion-graphics#faq\",\n    \"mainEntity\": [\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What is motion graphics?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Motion graphics brings graphic design to life: text, logos, icons and shapes are animated to share a message or build a brand. Unlike character animation, it is design-led.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What will I learn in this motion graphics course?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Design principles, Photoshop, Illustrator, storyboarding, After Effects, kinetic typography, logo animation, explainer videos, 3D basics, UI motion and Gen AI tools, ending with a showreel.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do I need design or animation experience?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"No. The course starts with design basics before any software, and every tool is taught from the first click.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Why is After Effects so important?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"After Effects is the industry-standard tool for motion graphics. Almost every motion graphic designer job asks for it, so it is the main tool of this course.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What is kinetic typography?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Animated text that moves in sync with music or voiceover. It is used in Reels, ads, explainer videos and title sequences.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Is this a motion graphic designer course for jobs in Delhi?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. It is a job-focused motion graphic designer course, taught at our Greater Kailash II campus in South Delhi, and every batch is also available online.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Is there a motion graphics course online?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. You can join the motion graphics course online or offline, with the same live classes, projects and placement support.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How is it different from the Graphic Design & Video Editing course?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Both share a design foundation. This course focuses on animation in After Effects, while the video editing course focuses on editing footage in Premiere Pro.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"How is Gen AI used in the course?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"AI tools are used in every module, and a dedicated module on motion graphics with Gen AI covers ChatGPT, Adobe Firefly and AI tools for animation, voice and subtitles.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What is a showreel and will I make one?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"A showreel is a 60 to 90 second video of your best motion work, and it is what employers watch first. Yes, you build one in the final module.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What jobs can I get after the course?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Motion Graphic Designer, Graphic Designer, Brand Animator, Explainer Video Designer, Social Media Motion Designer, or freelance motion work.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"Do you provide placement support?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"Yes. This motion graphics design course comes with 100% Placement Assistance: showreel review, Behance setup, mock interviews and referrals through our 250+ hiring partners. Top performers can get a paid in-house internship.\"\n            }\n        },\n        {\n            \"@type\": \"Question\",\n            \"name\": \"What certificates will I get?\",\n            \"acceptedAnswer\": {\n                \"@type\": \"Answer\",\n                \"text\": \"10+ certificates, including the DizitalAdda certificate in graphic design and motion graphics, Skill India recognition and a certificate for each live project.\"\n            }\n        }\n    ]\n}\r\n    "}} />


  
