<script dangerouslySetInnerHTML={{__html:"\r\n    let timeLeft = 15073;\r\n\r\n    function updateTimer() {\r\n        if (timeLeft <= 0) {\r\n            document.getElementById('hoursFixed').textContent = '00';\r\n            document.getElementById('minutesFixed').textContent = '00';\r\n            document.getElementById('secondsFixed').textContent = '00';\r\n            return;\r\n        }\r\n\r\n        let hours = Math.floor(timeLeft / 3600);\r\n        let minutes = Math.floor((timeLeft % 3600) / 60);\r\n        let seconds = timeLeft % 60;\r\n\r\n        document.getElementById('hoursFixed').textContent = String(hours).padStart(2, '0');\r\n        document.getElementById('minutesFixed').textContent = String(minutes).padStart(2, '0');\r\n        document.getElementById('secondsFixed').textContent = String(seconds).padStart(2, '0');\r\n\r\n        timeLeft--;\r\n    }\r\n    updateTimer();\r\n    setInterval(updateTimer, 1000);\r\n    "}} />


    
